// Get the canvas and 2d context
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

// Set the canvas dimensions
canvas.width = 400;
canvas.height = 400;

// Define some constants
const G = 9.81; // gravitational acceleration
const M = 0.1; // mass of the pendulum
const L = 100; // length of the pendulum
const FRICTION = 0.01; // coefficient of friction

// Initialize the pendulum state
let theta = 0; // initial angle
let omega = 0; // initial angular velocity
let t = 0; // time
let dt = 0.01; // time step

// Update the pendulum state according to the equations of motion
function update() {
  // Calculate the acceleration due to gravity
  const a = -G * Math.sin(theta) / L;

  // Update the angular velocity
  omega += a * dt;

  // Update the angle
  theta += omega * dt;

  // Apply friction
  omega *= 1 - FRICTION * dt;

  // Update the time
  t += dt;
}

// Draw the pendulum
function draw() {
  // Clear the canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw the pendulum bob
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 10, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();

  // Draw the pendulum arm
  ctx.beginPath();
  ctx.moveTo(canvas.width / 2, canvas.height / 2 - L * Math.sin(theta));
  ctx.lineTo(canvas.width / 2, canvas.height / 2);
  ctx.stroke();

  // Update the canvas
  canvas.requestAnimationFrame(draw);
}

// Release the pendulum when the button is clicked
document.getElementById('release-btn').addEventListener('click', () => {
  theta = radiansToDegrees(document.getElementById('initial-angle').value);
  omega = 0;
  t = 0;
  update();
  draw();
});

// Convert degrees to radians
function radiansToDegrees(radians) {
  return radians * 180 / Math.PI;
}

// Start the simulation
update();
draw();
